#!/usr/bin/env bash
set -Eeuo pipefail
mkdir -p out data baseline-published
exec > >(tee -a out/setup.log) 2>&1
# CPU-only FroDock uses no GPU. CUDA paths are still checked consistently for the pipeline.
select_cuda() {
    local root
    for root in /usr/local/cuda /usr/lib/cuda; do
        if [[ -x "$root/bin/nvcc" && -f "$root/include/cuda_runtime.h" && -f "$root/lib64/libcudart.so" ]]; then
            export CUDACXX="$root/bin/nvcc" CUDA_INCLUDE_DIR="$root/include" CUDA_LIBRARY="$root/lib64/libcudart.so" CUDAToolkit_ROOT="$root"
            export PATH="$root/bin:$PATH"
            ls -l "$CUDACXX" "$CUDA_INCLUDE_DIR/cuda_runtime.h" "$CUDA_LIBRARY"
            return
        fi
    done
    if [[ -x /usr/bin/nvcc && -f /usr/include/cuda_runtime.h && -f /usr/lib/x86_64-linux-gnu/libcudart.so ]]; then
        export CUDACXX=/usr/bin/nvcc CUDA_INCLUDE_DIR=/usr/include CUDA_LIBRARY=/usr/lib/x86_64-linux-gnu/libcudart.so
        ls -l "$CUDACXX" "$CUDA_INCLUDE_DIR/cuda_runtime.h" "$CUDA_LIBRARY"
    else
        echo 'No complete CUDA layout among probe-discovered locations.' >&2; exit 1
    fi
}
select_cuda
export CC=/usr/bin/gcc CXX=/usr/bin/g++
# Only the enabled repository recorded in the probe may supply apt packages.
missing=()
command -v mpirun >/dev/null || missing+=(openmpi-bin)
command -v mpic++ >/dev/null || missing+=(libopenmpi-dev)
[[ -f /usr/include/fftw3.h ]] || missing+=(libfftw3-dev)
if ((${#missing[@]})); then
    apt_args=(-o Dir::Etc::sourcelist=/etc/apt/sources.list.d/nvidia-docker-container.list -o Dir::Etc::sourceparts=-)
    sudo apt-get "${apt_args[@]}" update
    if ! sudo apt-get "${apt_args[@]}" install -y --no-install-recommends "${missing[@]}"; then
        echo "Required GNU/OpenMPI/FFTW dependencies unavailable from probe-listed apt source: ${missing[*]}" >&2
        exit 1
    fi
fi
for tool in /usr/bin/gcc /usr/bin/g++ /usr/bin/make python3 mpirun mpic++; do
    command -v "$tool" >/dev/null || { echo "Required tool unavailable: $tool" >&2; exit 1; }
done
# A local venv inherits stock torch, which is constrained against replacement.
if [[ ! -x baseline-published/venv/bin/python ]]; then
    python3 -m venv --system-site-packages baseline-published/venv || {
        echo 'Stock Python venv support required; probe-listed apt source cannot be assumed to provide python3-venv.' >&2; exit 1;
    }
fi
baseline-published/venv/bin/python - <<'PYTORCH'
from pathlib import Path
import torch
Path('baseline-published/stock-torch.txt').write_text('torch=='+torch.__version__+'\n')
PYTORCH
export PIP_CACHE_DIR="$PWD/out/pip-cache" PYTHONDONTWRITEBYTECODE=1
baseline-published/venv/bin/python -m pip install -c baseline-published/stock-torch.txt 'numpy<2' 'biotite>=1.0,<1.7' fastpdb pandas 'pyarrow>=12' torchtyping 'typeguard==2.13.3' typing_extensions 'pydantic>=2' tqdm plotly nbformat torch_geometric tabulate PyYAML scikit-learn google-cloud-storage gcsfs fire gemmi networkx mpire requests 'setuptools>=65.4' 'setuptools_scm>=7.1' 'build==0.10.0'
python3 - <<'PYFETCH'
import base64,hashlib,io,json,os,tarfile,urllib.request,zlib
from pathlib import Path
inventory=json.loads(zlib.decompress(base64.b64decode('')))
Path('baseline-published/inventory.json').write_text(json.dumps(inventory))
def fetch(url, dest, sha):
    dest=Path(dest); dest.parent.mkdir(parents=True,exist_ok=True)
    if dest.is_file() and hashlib.sha256(dest.read_bytes()).hexdigest()==sha: return
    with urllib.request.urlopen(url, timeout=120) as response: b=response.read()
    if hashlib.sha256(b).hexdigest()!=sha: raise RuntimeError('Checksum mismatch: '+url)
    tmp=dest.with_suffix(dest.suffix+'.tmp'); tmp.write_bytes(b); tmp.replace(dest)
def unpack(archive, target, prefix):
    target=Path(target)
    if (target/'.extracted').exists(): return
    target.mkdir(parents=True,exist_ok=True)
    with tarfile.open(archive) as t:
        for member in t.getmembers():
            parts=Path(member.name).parts
            if not parts or parts[0]!=prefix or '..' in parts: raise RuntimeError('Unsafe archive member')
            if len(parts)==1: continue
            member.name=str(Path(*parts[1:]))
            if member.issym() or member.islnk(): raise RuntimeError('Unexpected archive link')
            t.extract(member,target)
    (target/'.extracted').touch()
fetch('https://codeload.github.com/pinder-org/pinder/tar.gz/ebeb28a2f8411363cef722b7d293c978f7442672','out/pinder.tar.gz','b577532820ebbe5c16432b78c5e9c197690e863cb70a0a35a8ebcbe5277b76dd')
unpack('out/pinder.tar.gz','baseline-published/pinder','pinder-ebeb28a2f8411363cef722b7d293c978f7442672')
fetch('https://storage.googleapis.com/gke-dja-demo_static_assets/frodock3_linux64.tgz','out/frodock.tar.gz','91b9aeff747346046c7f8c4c92fa5749c9f082d8122ee9d2d4769855d35368f4')
unpack('out/frodock.tar.gz','baseline-published/frodock','frodock3_linux64')
for row in inventory:
    if row['input'] in ('index.parquet','metadata.parquet'):
        fetch(row['url'],Path('data')/row['input'],row['sha256'])
PYFETCH
SETUPTOOLS_SCM_PRETEND_VERSION=0.0.0 baseline-published/venv/bin/python -m pip install --no-deps --no-build-isolation ./baseline-published/pinder
# Published GNU configurations only; Intel configurations require a different compiler.
# No source rewriting. Rebuild the exact GNU binaries used by the published adapter.
if [[ ! -f baseline-published/frodock/.built-gnu ]]; then
    for component in libtools libpdb libvolume libfrm libbessel libfrodock libfrodockcluster libprotprot libsas; do
        make -C "baseline-published/frodock/src/$component/Release_gcc" clean
        make -C "baseline-published/frodock/src/$component/Release_gcc" -j8
    done
    for target in frodock/Release_MPI_gcc frodockgrid/Release_MPI_GCC frodockcluster/Release_gcc frodockview/Release_gcc; do
        make -C "baseline-published/frodock/src/$target" clean
        make -C "baseline-published/frodock/src/$target" -j8
    done
    touch baseline-published/frodock/.built-gnu
fi
for binary in frodock_mpi_gcc frodockgrid_mpi_gcc frodockcluster_gcc frodockview_gcc; do
    test -x "baseline-published/frodock/bin/$binary"
    if ldd "baseline-published/frodock/bin/$binary" 2>&1 | tee -a out/binary-libraries.log | grep -q 'not found'; then
        echo "Unresolved library for $binary" >&2; exit 1
    fi
done
export PINDER_DATA_DIR="$PWD/data" PINDER_RELEASE=2024-02
baseline-published/venv/bin/python -u - <<'PYPREP'
import hashlib,json,urllib.request
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from pinder.core import get_index
from pinder.core.index.utils import IndexEntry
case='7zj1__B1_P55265--7zj1__A1_P55265'
index=get_index()
rows=index[index.id==case]
if len(rows)!=1: raise RuntimeError('Fixed EXECUTION.json case not uniquely present in released index')
entry=IndexEntry(**rows.iloc[0].to_dict())
inventory={r['input']:r for r in json.loads(Path('baseline-published/inventory.json').read_text())}
paths=set()
for mapping in (entry.pdb_paths,entry.mapping_paths):
    for kind,values in mapping.items():
        values=values if isinstance(values,list) else [values]
        for value in values:
            if not value: continue
            if kind in ('holo_R','holo_L') and entry.test_system:
                value='test_set_pdbs/'+Path(value).name
            paths.add(value)
def acquire(name):
    row=inventory.get(name)
    url=row['url'] if row else 'https://pinderdata.org/2024-02/'+name
    path=Path('data')/name; path.parent.mkdir(parents=True,exist_ok=True)
    if path.exists() and (not row or hashlib.sha256(path.read_bytes()).hexdigest()==row['sha256']): return
    with urllib.request.urlopen(url,timeout=120) as response: b=response.read()
    digest=hashlib.sha256(b).hexdigest()
    if row and digest!=row['sha256']: raise RuntimeError('Input checksum mismatch: '+name)
    path.write_bytes(b)
    print(json.dumps({'input':name,'url':url,'sha256':digest,'intake_pin':bool(row)}),flush=True)
with ThreadPoolExecutor(max_workers=8) as pool: list(pool.map(acquire,sorted(paths)))
from pinder.methods.preprocess import prepare_inference_inputs
configs=prepare_inference_inputs(Path('data/prepared'),ids=[case],pairs='apo')
if len(configs)!=1: raise RuntimeError('Expected exactly one apo pair')
config=configs[0]
Path('data/prepared/config.json').write_text(json.dumps({k:str(v) for k,v in config.items()}))
print('Prepared fixed scale:',config)
print('FroDock material provenance: unverified_mirror; original-study identity unresolved.')
PYPREP
